INSERT INTO learning_handbooks(code,title,subtitle,description,source_pdf_path,source_note,sort_order,is_active) VALUES('helen-part1-vocab','HELEN TOEIC Part 1 Vocabulary','141 từ/cụm · 7 nhóm mô tả tranh','Bộ từ/cụm thường gặp cho TOEIC Part 1, giữ nguyên phiên âm, nghĩa và ví dụ từ Google Sheet người dùng cung cấp.','assets/handbooks/helen-toeic-part1-vocabulary.csv','User-provided Google Sheet integrated into YangLingo','40',1) ON DUPLICATE KEY UPDATE title=VALUES(title),subtitle=VALUES(subtitle),description=VALUES(description),source_pdf_path=VALUES(source_pdf_path),source_note=VALUES(source_note),sort_order=VALUES(sort_order),is_active=1;

INSERT INTO learning_handbook_sections(handbook_id,section_key,title,body_text,metadata_json,sort_order,is_active) SELECT id,'helen-eye-controlled-action','Eye-controlled action','Eye-controlled action
Nguồn: Google Sheet “HELEN TOEIC - TỪ VỰNG HAY GẶP PART 1 TOEIC”.
Cột nguồn: Từ vựng/Cụm từ · Phiên âm · Ý nghĩa · Ví dụ.

1. Review
   /rɪˈvjuː/
   Xem xét, duyệt lại
   She is reviewing a document.

2. Examine
   /ɪɡˈzæmɪn/
   Khảo sát, kiểm tra kỹ
   A scientist is examining a sample.

3. Look at
   /lʊk æt/
   Nhìn vào
   He is looking at the monitor.

4. Stare at
   /steər æt/
   Nhìn chằm chằm
   The men are staring at each other.

5. Leaf through
   /liːf θruː/
   Lật giở lướt qua
   She is leafing through a magazine.

6. Face each other
   /feɪs iːtʃ ˈʌðər/
   Đối mặt nhau
   Two men are facing each other across the table.

7. Inspect
   /ɪnˈspekt/
   Thanh tra, kiểm tra chi tiết
   An engineer is inspecting the engine parts.

8. Browse
   /braʊz/
   Xem lướt, xem hàng
   Customers are browsing the merchandise in the shop.

9. Gaze at
   /ɡeɪz æt/
   Nhìn chăm chú, ngắm nhìn
   A woman is gazing at the artwork on the wall.

10. Admire
   /ədˈmaɪər/
   Chiêm ngưỡng
   Tourists are admiring the view of the harbor.

11. Glance at
   /ɡlɑːns æt/
   Liếc nhìn nhanh
   He is glancing at his wristwatch.

12. Scrutinize
   /ˈskruːtənaɪz/
   Soi kỹ, nghiên cứu cẩn thận
   She is scrutinizing the blueprint on the table.','{"source_sheet":"Eye-controlled action","toeic_part":"1","recommended_use":"Nghe ví dụ → tự nhớ nghĩa → xem đáp án → lưu từ/cụm chưa chắc vào SRS."}',1,1 FROM learning_handbooks WHERE code='helen-part1-vocab' ON DUPLICATE KEY UPDATE title=VALUES(title),body_text=VALUES(body_text),metadata_json=VALUES(metadata_json),sort_order=VALUES(sort_order),is_active=1;

INSERT INTO learning_handbook_sections(handbook_id,section_key,title,body_text,metadata_json,sort_order,is_active) SELECT id,'helen-manual-operation','Manual operation','Manual operation
Nguồn: Google Sheet “HELEN TOEIC - TỪ VỰNG HAY GẶP PART 1 TOEIC”.
Cột nguồn: Từ vựng/Cụm từ · Phiên âm · Ý nghĩa · Ví dụ.

1. Hold / Hold on to
   /həʊld ɒn tuː/
   Cầm, nắm, bám chặt vào
   Some people are holding on to the railing.

2. Reach for
   /riːtʃ fɔːr/
   Với tay lấy
   She is reaching for a lamp.

3. Push
   /pʊʃ/
   Đẩy
   Some shoppers are pushing carts.

4. Pull
   /pʊl/
   Kéo
   Travelers are pulling their suitcases.

5. Point at
   /pɔɪnt æt/
   Chỉ tay vào
   A man is pointing at a painting.

6. Gesture
   /ˈdʒestʃər/
   Ra hiệu bằng tay
   He is gesturing with his hands during the talk.

7. Take down
   /teɪk daʊn/
   Gỡ xuống, tháo xuống
   They are taking down a banner from the wall.

8. Arrange
   /əˈreɪndʒ/
   Sắp xếp, cắm (hoa)
   Flowers are being arranged in a vase.

9. Chop up
   /tʃɒp ʌp/
   Chặt nhỏ, thái vụn
   They are chopping up some vegetables.

10. Hammer
   /ˈhæmər/
   Đóng búa, nện
   A carpenter is hammering a nail into the board.

11. Polish
   /ˈpɒlɪʃ/
   Đánh bóng
   A man is polishing some boots.

12. Display
   /dɪˈspleɪ/
   Trưng bày
   A merchant is displaying some items on the shelf.

13. Roll up
   /rəʊl ʌp/
   Xắn lên, cuộn lại
   He is rolling up his sleeves.

14. Hand
   /hænd/
   Đưa, trao tay
   A man is handing money to a cashier.

15. Load
   /ləʊd/
   Bốc, chất hàng lên
   Workers are loading some packages into a truck.

16. Unload
   /ʌnˈləʊd/
   Dỡ hàng xuống
   Some men are unloading cargo from the vessel.

17. Wheel
   /wiːl/
   Đẩy xe có bánh
   They are wheeling the cart into the room.

18. Water
   /ˈwɔːtər/
   Tưới nước
   She is watering a potted plant.

19. Pack
   /pæk/
   Đóng gói
   A traveler is packing a suitcase.

20. Install
   /ɪnˈstɔːl/
   Lắp đặt
   He is installing a bookshelf in the office.

21. Trim
   /trɪm/
   Cắt tỉa
   A gardener is trimming the bushes.

22. Mop
   /mɒp/
   Lau sàn
   A custodian is mopping the floor.

23. Sweep
   /swiːp/
   Quét dọn
   A worker is sweeping the pavement with a broom.

24. Fasten
   /ˈfɑːsn/
   Cài, thắt chặt
   The passenger is fastening his seatbelt.

25. Grasp / Grip
   /ɡrɑːsp/ - /ɡrɪp/
   Nắm chặt, túm lấy
   She is grasping the handle of the briefcase.

26. Stack
   /stæk/
   Xếp chồng lên
   The clerk is stacking plastic crates in the corner.

27. Unroll
   /ʌnˈrəʊl/
   Mở/trải cuộn ra
   They are unrolling a large blueprint on the desk.

28. Assemble
   /əˈsembl/
   Lắp ráp
   Technicians are assembling some electronic components.

29. Operate
   /ˈɒpəreɪt/
   Vận hành máy móc
   A worker is operating heavy machinery.

30. Adjust
   /əˈdʒʌst/
   Điều chỉnh
   He is adjusting the focus on the microscope.

31. Distribute
   /dɪˈstrɪbjuːt/
   Phân phát
   She is distributing handouts to the attendees.

32. Fold
   /fəʊld/
   Gấp lại
   A clerk is folding blankets on the display table.

33. Wipe
   /waɪp/
   Lau chùi
   The waiter is wiping the countertop with a cloth.','{"source_sheet":"Manual operation","toeic_part":"1","recommended_use":"Nghe ví dụ → tự nhớ nghĩa → xem đáp án → lưu từ/cụm chưa chắc vào SRS."}',2,1 FROM learning_handbooks WHERE code='helen-part1-vocab' ON DUPLICATE KEY UPDATE title=VALUES(title),body_text=VALUES(body_text),metadata_json=VALUES(metadata_json),sort_order=VALUES(sort_order),is_active=1;

INSERT INTO learning_handbook_sections(handbook_id,section_key,title,body_text,metadata_json,sort_order,is_active) SELECT id,'helen-movement-sports-posture','Movement, Sports & Posture','Movement, Sports & Posture
Nguồn: Google Sheet “HELEN TOEIC - TỪ VỰNG HAY GẶP PART 1 TOEIC”.
Cột nguồn: Từ vựng/Cụm từ · Phiên âm · Ý nghĩa · Ví dụ.

1. Sit across from
   /sɪt əˈkrɒs frɒm/
   Ngồi đối diện với
   They are sitting across from each other.

2. Lie down / Lie on
   /laɪ daʊn/
   Nằm xuống / Nằm trên
   A man is lying down on a sofa.

3. Lean against
   /liːn əˈɡenst/
   Dựa, tựa lưng vào
   The men are leaning against a fence.

4. Rest
   /rest/
   Nghỉ ngơi
   Some women are resting under a shade tree.

5. Hike
   /haɪk/
   Đi bộ đường dài
   Hikers are trekking along a mountain trail.

6. Ride
   /raɪd/
   Cưỡi, lái xe
   The men are riding horses along the coast.

7. Stroll
   /strəʊl/
   Đi dạo thong thả
   People are strolling through the botanical garden.

8. Cross
   /krɒs/
   Băng qua đường
   Pedestrians are crossing at the intersection.

9. Board
   /bɔːd/
   Lên tàu/xe/máy bay
   Passengers are boarding a commuter train.

10. Get off
   /ɡet ɒf/
   Xuống tàu/xe
   Some men are getting off a bus.

11. Walk up / Ascend
   /əˈsend/
   Đi lên (cầu thang)
   She is ascending the flight of stairs.

12. Descend
   /dɪˈsend/
   Đi xuống (cầu thang)
   She is descending the staircase carefully.

13. Lean over
   /liːn ˈəʊvər/
   Cúi người qua
   A chef is leaning over the counter to serve food.

14. Kneel down
   /niːl daʊn/
   Quỳ gối xuống
   A landscaper is kneeling down on the lawn.

15. Crouch / Squat
   /kraʊtʃ/ - /skwɒt/
   Ngồi xổm, khom người
   He is crouching down to inspect the tire.

16. Disembark
   /ˌdɪsɪmˈbɑːk/
   Xuống (tàu thuyền, máy bay)
   Passengers are disembarking from the ferry.

17. Embark
   /ɪmˈbɑːk/
   Lên tàu/thuyền
   Commuters are embarking onto the vessel.

18. Bend down
   /bend daʊn/
   Cúi gập người
   She is bending down to pick up a dropped folder.

19. Disperse
   /dɪˈspɜːs/
   Giải tán, tản ra
   The crowd is dispersing after the concert ended.

20. Gather
   /ˈɡæðər/
   Tập trung lại
   Audience members are gathering around the performer.','{"source_sheet":"Movement, Sports & Posture","toeic_part":"1","recommended_use":"Nghe ví dụ → tự nhớ nghĩa → xem đáp án → lưu từ/cụm chưa chắc vào SRS."}',3,1 FROM learning_handbooks WHERE code='helen-part1-vocab' ON DUPLICATE KEY UPDATE title=VALUES(title),body_text=VALUES(body_text),metadata_json=VALUES(metadata_json),sort_order=VALUES(sort_order),is_active=1;

INSERT INTO learning_handbook_sections(handbook_id,section_key,title,body_text,metadata_json,sort_order,is_active) SELECT id,'helen-clothing-daily-life','Clothing & Daily Life','Clothing & Daily Life
Nguồn: Google Sheet “HELEN TOEIC - TỪ VỰNG HAY GẶP PART 1 TOEIC”.
Cột nguồn: Từ vựng/Cụm từ · Phiên âm · Ý nghĩa · Ví dụ.

1. Wear
   /weər/
   Đang mặc/đeo (trạng thái)
   He is wearing a suit and tie.

2. Put on
   /pʊt ɒn/
   Mặc vào, xỏ vào (hành động)
   She is putting on protective glasses.

3. Try on
   /traɪ ɒn/
   Mặc thử, đi thử
   A man is trying on a pair of leather shoes.

4. Change clothes
   /tʃeɪndʒ kləʊðz/
   Thay trang phục
   She is changing clothes in the dressing room.

5. Prepare a meal
   /prɪˈpeər ə miːl/
   Nấu nướng, chuẩn bị bữa ăn
   She is preparing her meal on the counter.

6. Have dessert
   /hæv dɪˈzɜːt/
   Ăn món tráng miệng
   She is having some dessert at the cafe.

7. Boil
   /bɔɪl/
   Đun sôi
   They are boiling water on a stove.

8. Perform
   /pəˈfɔːm/
   Trình diễn
   Musicians are performing indoors on stage.

9. Pay for
   /peɪ fɔːr/
   Thanh toán tiền
   A woman is paying for some groceries.

10. Fasten
   /ˈfɑːsn/
   Cài nút, khóa lại
   The attendant is fastening her vest.

11. Button / Unbutton
   /ˈbʌtn/ - /ʌnˈbʌtn/
   Cài cúc / Mở cúc
   He is buttoning up his overcoat.

12. Slip on / Slip off
   /slɪp ɒn/ - /slɪp ɒf/
   Xỏ nhanh vào / Tháo tuột ra
   The runner is slipping on his sneakers.

13. Sip
   /sɪp/
   Nhấp từng ngụm
   A patron is sipping a hot beverage.

14. Sample
   /ˈsɑːmpl/
   Nếm thử đồ ăn
   Shoppers are sampling food at a market stall.

15. Dine
   /daɪn/
   Dùng bữa
   Guests are dining on an outdoor patio.','{"source_sheet":"Clothing & Daily Life","toeic_part":"1","recommended_use":"Nghe ví dụ → tự nhớ nghĩa → xem đáp án → lưu từ/cụm chưa chắc vào SRS."}',4,1 FROM learning_handbooks WHERE code='helen-part1-vocab' ON DUPLICATE KEY UPDATE title=VALUES(title),body_text=VALUES(body_text),metadata_json=VALUES(metadata_json),sort_order=VALUES(sort_order),is_active=1;

INSERT INTO learning_handbook_sections(handbook_id,section_key,title,body_text,metadata_json,sort_order,is_active) SELECT id,'helen-objects-equipment','Objects & Equipment','Objects & Equipment
Nguồn: Google Sheet “HELEN TOEIC - TỪ VỰNG HAY GẶP PART 1 TOEIC”.
Cột nguồn: Từ vựng/Cụm từ · Phiên âm · Ý nghĩa · Ví dụ.

1. Apron
   /ˈeɪprən/
   Tạp dề
   They are wearing protective aprons.

2. Safety helmet / Hard hat
   /ˈseɪfti ˈhelmɪt/
   Mũ bảo hộ công trình
   A worker is putting on a safety helmet.

3. Suit and tie
   /suːt ænd taɪ/
   Bộ vest và cà vạt
   The executive is dressed in a suit and tie.

4. Boots
   /buːts/
   Đôi ủng, bốt bảo hộ
   A man is polishing some heavy boots.

5. Cart / Trolley
   /kɑːt/ - /ˈtrɒli/
   Xe đẩy hàng
   They are wheeling the loaded cart.

6. Tray
   /treɪ/
   Khay bê đồ ăn
   The servers are carrying trays to a sink.

7. Sink
   /sɪŋk/
   Bồn rửa
   Dishes are stacked inside the kitchen sink.

8. Stove
   /stəʊv/
   Bếp nấu
   Pots have been placed on the stove.

9. Shelf / Bookshelf
   /ʃelf/ - /ˈbʊkʃelf/
   Kệ / Giá sách
   He is taking a book off the shelf.

10. Nail
   /neɪl/
   Cây đinh
   A man is hammering a nail into the wood.

11. Suitcase / Luggage
   /ˈsuːtkeɪs/ - /ˈlʌɡɪdʒ/
   Vali / Hành lý
   Suitcases are lined up in the terminal.

12. Package / Parcel
   /ˈpækɪdʒ/ - /ˈpɑːsl/
   Kiện hàng, bưu kiện
   They are loading some packages into a van.

13. Office equipment
   /ˈɒfɪs ɪˈkwɪpmənt/
   Máy móc văn phòng
   A technician is servicing the office equipment.

14. Furniture
   /ˈfɜːnɪtʃər/
   Đồ nội thất
   The workers are moving some office furniture.

15. Railing / Handrail
   /ˈreɪlɪŋ/ - /ˈhændreɪl/
   Lan can, tay vịn
   Some people are holding on to the railing.

16. Label
   /ˈleɪbl/
   Nhãn dán, mác
   Labels have been attached to the garments.

17. Vase
   /vɑːz/
   Bình/lọ hoa
   Flowers are being arranged in a ceramic vase.

18. Projector
   /prəˈdʒektər/
   Máy chiếu
   A projector is mounted to the ceiling.

19. Parasol
   /ˈpærəsɒl/
   Dù lớn che nắng
   Parasols have been set up along the beach.

20. Beach towel
   /biːtʃ ˈtaʊəl/
   Khăn tắm biển
   Beach towels have been draped over the chairs.

21. Stepladder / Ladder
   /ˈsteplædər/ - /ˈlædər/
   Thang gấp / Thang leo
   A painter is standing on a stepladder.

22. Wheelbarrow
   /ˈwiːlbærəʊ/
   Xe rùa (chở đất/đá)
   A wheelbarrow is filled with gardening soil.

23. Lamppost / Streetlight
   /ˈlæmppəʊst/
   Cột đèn đường
   Bicycles are chained to a metal lamppost.

24. Hydrant
   /ˈhaɪdrənt/
   Trụ cứu hỏa
   A vehicle is parked next to a fire hydrant.

25. Scaffolding
   /ˈskæfəldɪŋ/
   Giàn giáo xây dựng
   Workers are climbing the construction scaffolding.

26. Display case / Showcase
   /ˈdɪspleɪ keɪs/
   Tủ kính trưng bày
   Jewelry is exhibited inside a display case.

27. Conveyor belt
   /kənˈveɪə belt/
   Băng chuyền
   Suitcases are moving along a conveyor belt.

28. Planter / Flowerpot
   /ˈplɑːntər/
   Chậu cây cảnh
   Flowerpots have been arranged along the patio.','{"source_sheet":"Objects & Equipment","toeic_part":"1","recommended_use":"Nghe ví dụ → tự nhớ nghĩa → xem đáp án → lưu từ/cụm chưa chắc vào SRS."}',5,1 FROM learning_handbooks WHERE code='helen-part1-vocab' ON DUPLICATE KEY UPDATE title=VALUES(title),body_text=VALUES(body_text),metadata_json=VALUES(metadata_json),sort_order=VALUES(sort_order),is_active=1;

INSERT INTO learning_handbook_sections(handbook_id,section_key,title,body_text,metadata_json,sort_order,is_active) SELECT id,'helen-scenes-surroundings','Scenes & Surroundings','Scenes & Surroundings
Nguồn: Google Sheet “HELEN TOEIC - TỪ VỰNG HAY GẶP PART 1 TOEIC”.
