INSERT INTO learning_handbook_sections(handbook_id,section_key,title,body_text,metadata_json,sort_order,is_active) SELECT id,'helen-object-states-arrangements','Object States & Arrangements','Object States & Arrangements
Nguồn: Google Sheet “HELEN TOEIC - TỪ VỰNG HAY GẶP PART 1 TOEIC”.
Cột nguồn: Từ vựng/Cụm từ · Phiên âm · Ý nghĩa · Ví dụ.

1. Be surrounded by
   /səˈraʊndɪd baɪ/
   Được bao quanh bởi
   A circular table is surrounded by chairs.

2. Be lined up
   /laɪnd ʌp/
   Được xếp thành hàng
   Some suitcases are lined up in the hallway.

3. In a row
   /ɪn ə rəʊ/
   Thành một hàng thẳng
   Some machines are placed in a row.

4. Be attached to
   /əˈtætʃt tuː/
   Được gắn chặt vào
   A projector is attached to the ceiling.

5. Be positioned upside down
   /pəˈzɪʃnd ˈʌpsaɪd daʊn/
   Được đặt úp ngược
   Some chairs are positioned upside down.

6. Be left open
   /left ˈəʊpən/
   Được để mở
   A storage room door has been left open.

7. Be piled (up)
   /paɪld ʌp/
   Được chất đống, xếp chồng
   Some boxes have been piled next to a desk.

8. Be parked on / next to
   /pɑːkt/
   Được đỗ, đậu xe
   Cars are parked on one side of the road.

9. Be hung on
   /hʌŋ ɒn/
   Được treo trên
   A decorative painting is hung on the wall.

10. Be propped against
   /prɒpt əˈɡenst/
   Được dựng nghiêng, dựa vào
   A wooden ladder is propped against the shed.

11. Be mounted on
   /ˈmaʊntɪd ɒn/
   Được lắp cố định trên
   Light fixtures are mounted on the brick wall.

12. Be scattered across
   /ˈskætəd əˈkrɒs/
   Bị rải rác khắp nơi
   Fallen leaves are scattered across the walkway.

13. Be stacked on top of
   /stækt ɒn tɒp ɒv/
   Được xếp chồng lên trên
   Plates are stacked on top of one another.

14. Be situated / located
   /ˈsɪtʃueɪtɪd/
   Tọa lạc, nằm ở vị trí
   A bench is situated beside the flowerbed.

15. Be displayed for sale
   /dɪˈspleɪd fɔː seɪl/
   Được bày bán
   Fresh produce is displayed for sale outdoors.

16. Be suspended from
   /səˈspendɪd frɒm/
   Được treo lơ lửng từ
   Chardeliers are suspended from the high ceiling.

17. Be docked at
   /dɒkt æt/
   Được neo đậu tại bến
   Several yachts are docked at the marina.

18. Be unoccupied / vacant
   /ˌʌnˈɒkjupaɪd/
   Trống rỗng, không người ngồi
   All the seats in the lounge are unoccupied.

19. Be partially shaded
   /ˈpɑːʃəli ˈʃeɪdɪd/
   Được che bóng một phần
   The outdoor patio is partially shaded by an awning.

20. Be cordoned off
   /ˈkɔːdnd ɒf/
   Bị chăng dây phong tỏa
   The road section has been cordoned off with cones.','{"source_sheet":"Object States & Arrangements","toeic_part":"1","recommended_use":"Nghe ví dụ → tự nhớ nghĩa → xem đáp án → lưu từ/cụm chưa chắc vào SRS."}',7,1 FROM learning_handbooks WHERE code='helen-part1-vocab' ON DUPLICATE KEY UPDATE title=VALUES(title),body_text=VALUES(body_text),metadata_json=VALUES(metadata_json),sort_order=VALUES(sort_order),is_active=1;

